def update_bootstrap_stage(stage: str, status: str) -> None:
    path = EOS / "workflow.tsv"
    rows = read_tsv(path)
    found = False
    for row in rows:
        if row["stage"] == stage:
            row["status"] = status
            row["completed_at"] = now_iso() if status == "COMPLETE" else "-"
            found = True
            break
    if not found:
        raise EosError(f"Stage not found: {stage}")
    fields = [
        "order",
        "stage",
        "phase",
        "primary_output",
        "lead",
        "reviewer",
        "gate",
        "status",
        "completed_at",
    ]
    write_tsv(path, fields, rows)


