    "specifications",
    "testing",
    "vision",
}

NORMATIVE_ROOT_FILES = {
    ".editorconfig",
    ".gitattributes",
    ".githubignore",
    ".gitignore",
    "CODE_OF_CONDUCT.md",
    "CONTRIBUTING.md",
    "LICENSE",
    "SECURITY.md",
}

DOCUMENT_TYPE_BY_ROOT = {
    "architecture": "architecture",
    "docs": "published-documentation",
    "engineering": "engineering-control",
    "governance": "governance",
    "journal": "journal",
    "operations": "operations",
