    "research": "research",
    "scripts": "automation",
    "security": "security",
    "specifications": "specification",
    "testing": "quality-assurance",
    "tools": "tooling",
    "vision": "vision",
}

LANGUAGE_BY_NAME = {
    ".editorconfig": "editorconfig",
    ".gitattributes": "gitattributes",
    ".githubignore": "gitignore-patterns",
    ".gitignore": "gitignore",
    "CODEOWNERS": "codeowners",
    "LICENSE": "plain-text",
    "Makefile": "make",
}

LANGUAGE_BY_SUFFIX = {
    ".adoc": "asciidoc",
    ".bash": "bash",
    ".cfg": "ini",
    ".conf": "configuration",
    ".css": "css",
    ".go": "go",
    ".graphql": "graphql",
    ".html": "html",
    ".ini": "ini",
    ".java": "java",
    ".js": "javascript",
    ".json": "json",
    ".jsonl": "json-lines",
    ".jsx": "javascript-jsx",
    ".md": "markdown",
    ".py": "python",
    ".rs": "rust",
    ".rst": "restructuredtext",
    ".sh": "bash",
    ".sql": "sql",
