                raise EosError(f"{args.override_id} is {row.get('status')}, not ACTIVE")
            row["status"] = "EXPIRED"
            save_overrides(rows)
            append_event(
                "OVERRIDE_EXPIRED",
                target=row.get("target", ""),
                action=row.get("gate", ""),
