    elif kind == "WC":
        allowed, new = {"AUTHORIZED", "ACTIVE"}, "ACTIVE"
    elif kind == "WP":
        allowed, new = {"AUTHORIZED", "IN_PROGRESS"}, "IN_PROGRESS"
    elif kind == "MNT":
        allowed, new = {"OPEN", "PLANNED", "IN_PROGRESS"}, "IN_PROGRESS"
    else:
