AC_RE = re.compile(r"^\s*-\s*\[[ xX]\]\s*(AC-[A-Z0-9][A-Z0-9-]*)\s*(?::|—|-)\s*(.+)$")
SECRET_PATTERNS = {
    "private-key": re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----"),
